pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        // Deploy a simple token contract that tracks balances
        SimpleToken token = new SimpleToken();
        // Fund the from address
        vm.deal(from, 1 ether);
        // Mint tokens to from address
        token.mint(from, 1000 ether);
        // Approve the C contract to spend from's tokens
        vm.prank(from);
        token.approve(address(c), type(uint256).max);
        // Record balance before
        uint256 before = token.balanceOf(from);
        // Call transfer
        c.transfer(from, address(token), _tos, v);
        // Record balance after
        uint256 after = token.balanceOf(from);
        // The from address should have lost v * _tos.length tokens
        assertTrue(after == before - v * _tos.length);
    }
}

contract SimpleToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(allowance[from][msg.sender] >= value);
        require(balanceOf[from] >= value);
        allowance[from][msg.sender] -= value;
        balanceOf[from] -= value;
        balanceOf[to] += value;
        return true;
    }
}

